// 강성호 2026-10-11: 동결 v4의 TOPIK 의미·해설·쓰기 기준 결함을 별도 v5에서 수정한다. 독립 재검수 전 비공개다.
import type { DraftItem } from "../learning-path-2026-10-11/data.js";

type Localized = { ko: string; ja: string; en: string };
const l = (ko: string, ja: string, en: string): Localized => ({ ko, ja, en });
const choices = (...values: string[]) => values.map(value => l(value, value, value));
const question = (kind: "grammar" | "vocab" | "reading" | "listening", text: string): Localized => {
  const instruction = {
    grammar: l("( )에 들어갈 가장 알맞은 표현을 고르십시오.", "（ ）に入る最も適切な韓国語表現を選んでください。", "Choose the most appropriate Korean expression for the blank."),
    vocab: l("다음 상황에 알맞은 한국어 표현을 고르십시오.", "次の状況に合う韓国語表現を選んでください。", "Choose the Korean expression that best fits the situation."),
    reading: l("다음 글을 읽고 질문에 답하십시오.", "次の韓国語の文章を読んで質問に答えてください。", "Read the Korean passage and answer the question."),
    listening: l("음성을 듣고 질문에 답하십시오.", "韓国語の音声を聞いて質問に答えてください。", "Listen to the Korean audio and answer the question."),
  }[kind];
  return l(`${instruction.ko}\n${text}`, `${instruction.ja}\n${text}`, `${instruction.en}\n${text}`);
};
export const TOPIK_V5_ITEM_PATCHES: Record<string, Partial<DraftItem>> = {};
const patch = (suffix: string, value: Partial<DraftItem>) => { TOPIK_V5_ITEM_PATCHES[`lp4-topik-${suffix}`] = { ...TOPIK_V5_ITEM_PATCHES[`lp4-topik-${suffix}`], ...value }; };

